package com.lexorion.payroll.api;
import static com.lexorion.payroll.api.CompensationDtos.*;import com.lexorion.payroll.service.ComponentDefinitionService;import jakarta.validation.Valid;import java.util.List;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/payroll/components")@PreAuthorize("hasRole('ADMIN')")public class ComponentDefinitionController{private final ComponentDefinitionService service;public ComponentDefinitionController(ComponentDefinitionService s){service=s;}@GetMapping public List<ComponentResponse>list(){return service.list();}@PostMapping public ResponseEntity<ComponentResponse>create(@Valid@RequestBody CreateComponent r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));}@PatchMapping("/{componentKey}")public ComponentResponse update(@PathVariable String componentKey,@Valid@RequestBody UpdateComponent r){return service.update(componentKey,r);}@DeleteMapping("/{componentKey}")public ComponentResponse deactivate(@PathVariable String componentKey){return service.deactivate(componentKey);}}
